package com.suiren.mirea.playback;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class PlaybackOrderTest {
 private JSONArray entries(String... ids)throws Exception{JSONArray a=new JSONArray();for(String id:ids)a.put(new JSONObject().put("id",id).put("kind",id.equals("book")?"pdf":"audio"));return a;}
 @Test public void repeatWrapsAndOneItemSeriesCanRepeat()throws Exception{PlaybackOrder q=new PlaybackOrder(new Random(1));assertEquals("a",q.plan(entries("a","book","b"),"b","s",1,true,false).target.getString("id"));assertEquals("b",q.plan(entries("a","book","b"),"a","s",-1,true,false).target.getString("id"));assertEquals("a",q.plan(entries("a"),"a","s",1,true,false).target.getString("id"));assertNull(q.plan(entries("a"),"a","s",1,false,false));}
 @Test public void shuffleHasNoRepeatUntilCycleEndsAndPreviousFollowsActualHistory()throws Exception{JSONArray assets=entries("a","b","book","c","d");PlaybackOrder q=new PlaybackOrder(new Random(7));String current="a";ArrayList<String> history=new ArrayList<>();history.add(current);for(int i=0;i<3;i++){PlaybackOrder.Plan p=q.plan(assets,current,"s",1,false,true);assertNotNull(p);q=p.order;current=p.target.getString("id");history.add(current);}assertEquals(4,new HashSet<>(history).size());assertNull(q.plan(assets,current,"s",1,false,true));PlaybackOrder.Plan back=q.plan(assets,current,"s",-1,false,true);assertEquals(history.get(2),back.target.getString("id"));PlaybackOrder.Plan forward=back.order.plan(assets,history.get(2),"s",1,false,true);assertEquals(current,forward.target.getString("id"));assertNotEquals(current,q.plan(assets,current,"s",1,true,true).target.getString("id"));}
 @Test public void cancelledPlansDoNotConsumeQueueAndFreshListsExcludeRemovedAssets()throws Exception{PlaybackOrder q=new PlaybackOrder(new Random(3));JSONArray assets=entries("a","b","c");PlaybackOrder.Plan p=q.plan(assets,"a","s",1,false,true);assertNotNull(p);assertNotNull(q.plan(assets,"a","s",1,false,true));PlaybackOrder.Plan next=p.order.plan(entries(p.target.getString("id"),"new"),p.target.getString("id"),"s",1,false,true);assertEquals("new",next.target.getString("id"));assertNull(q.plan(entries("x"),"a","s",1,true,true));}
}
